#!/bin/bash
# Task 153-w10-footprint-ab -- meshsim sim/ WORKER10 (branch sim-w10; kit: before 378931d, after 51c9e5b). TIMING TASK: keep the box quiet while it runs.
# The footprint tooling (W10), before/after interleaved: before 378931d (main), after 51c9e5b (the engine's carving kept at build
# for Internals::regions, bench_chip's --trace-map; nothing in the cycle path). The chip on one thread (the boot, wfi,
# regs) and the boot at 6 threads, the mesh and synth on one thread; test_golden and test_chip per revision (the kit now
# carries every input); digests equal. 5 processes. ~5 min.
# From an embedded kit (sim/ at each revision named above). Writes only results/153-w10-footprint-ab/. Scratch in /tmp, removed first
# and at the end. Safe to re-run.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/153-w10-footprint-ab; mkdir -p "$RES"; rm -f "$RES/raw.txt"
W=/tmp/w10-153-w10-footprint-ab; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "e1f9d5c5ce6b153fe5a15ff181b60c83ba2f40db763bf2dd03e95f543e3584f6" ] || { echo "kit sha256 mismatch (want e1f9d5c5ce6b153fe5a15ff181b60c83ba2f40db763bf2dd03e95f543e3584f6)"; exit 2; }
mkdir -p "$W/kit" && tar -xzf "$W/kit.tgz" -C "$W/kit" || exit 2
KITS="before after"
FAILS=0; FAIL=0
sec() { echo; echo "==== $*  [$(date +%T)]"; }
verdict() { echo "VERDICT $1: $2"; [ "$2" = PASS ] || FAIL=1; }
START=$(date +%s)
{
sec "machine (D21)"; . "$W/kit/after/sim/tools/machine.sh" "${QUEST_P_CPUS:-}" "${QUEST_E_CPUS:-}"; machine_record "$RES/machine.txt"; uptime
echo "kit: before 378931d, after 51c9e5b"
# Shared by W10's task bodies. run TAG CPUSET cmd...: one run under taskset (and perf stat when PERF=1: cycles,
# instructions, L1d load misses, LLC load misses, summed per core type); appends "TAG <bench line> [perf: ...]" to
# $RES/raw.txt. field NAME: a key=value field of stdin's lines.
run() {
  local tag=$1 cpus=$2; shift 2
  command -v perf > /dev/null || PERF=0
  if [ "${PERF:-0}" = 1 ]; then
    taskset -c "$cpus" perf stat -x, -e cycles,instructions,L1-dcache-load-misses,LLC-load-misses -o "$W/perf.csv" -- "$@" \
      > "$W/out.txt" 2> "$W/err.txt"
  else
    taskset -c "$cpus" "$@" > "$W/out.txt" 2> "$W/err.txt"
  fi
  local rc=$?
  local line; line=$(grep -E '^(threads|chip) ' "$W/out.txt" | tail -1)
  if [ $rc -ne 0 ] || [ -z "$line" ]; then echo "RUNFAIL $tag rc=$rc: $*"; head -5 "$W/err.txt"; FAILS=$((FAILS + 1)); return 1; fi
  local pc=""
  [ "${PERF:-0}" = 1 ] && pc=" perf: $(awk -F, '$1 ~ /^[0-9]+$/ { n=split($3,a,"/"); ev=(n>1)?a[2]:a[1]; k=(a[1]=="cpu_atom")?"atom":"core";
      v[k "_" ev]+=$1 } END { for (x in v) printf "%s=%s ", x, v[x] }' "$W/perf.csv")"
  echo "$tag $line$pc" | tee -a "$RES/raw.txt"
}
field() { grep -o "$1=[^ ]*" | cut -d= -f2; }
# med TAG FIELD: the median of FIELD over raw.txt's lines starting "TAG "
med() { grep "^$1 " "$RES/raw.txt" | field "$2" | sort -g | awk '{ a[NR]=$1 } END { if (NR) print a[int((NR+1)/2)]; else print "-" }'; }
# Task body (WORKER10): the framework's cost per step, before/after interleaved: W9's chip on one thread (the boot,
# wfi, regs; bench_chip --reps 9, in-process repeats) and at 6 threads by tiles (the boot), W4's mesh and the synthetic
# chip on one thread (bench_threads form 2, 60,000 cycles), perf stat on the chip's boot. REPS (default 5) processes.
# The goldens need the kit to carry golden-m2 and ref/meshsim/test (KIT_EXCLUDE): Quest 149 lacked the latter.
REPS=${REPS:-5}
sec "build (clang release, D18) and the goldens (test_golden, test_chip: clang release)"
for k in $KITS; do
  ( cd "$W/kit/$k/sim" && make -j8 CC_NAME=clang MODE=release build/clang-release/bench_chip build/clang-release/bench_threads \
      build/clang-release/test_golden build/clang-release/test_chip > "$RES/build-$k.log" 2>&1 ) || { tail -20 "$RES/build-$k.log"; verdict "build $k" FAIL; exit 1; }
  ( cd "$W/kit/$k/sim" && ./build/clang-release/test_golden > "$RES/golden-$k.log" 2>&1 && ./build/clang-release/test_chip >> "$RES/golden-$k.log" 2>&1 ) \
    && verdict "test_golden, test_chip $k" PASS || verdict "test_golden, test_chip $k" FAIL
done
P1=$(take 1 "$P_ONE"); C6=$(take 6 "$PLACE")
crun() { local tag=$1 cpus=$2 k=$3; shift 3; ( cd "$W/kit/$k/sim" && run "$tag" "$cpus" ./build/clang-release/bench_chip "$@" ); }
for rep in $(seq $REPS); do for k in $KITS; do B=$W/kit/$k/sim/build/clang-release/bench_threads
  for p in sort wfi regs; do crun "$k one-$p" "$P1" $k --prog $p --threads 1 --cpus "$P1" --reps 9; done
  [ $rep = 1 ] && PERF=1 crun "$k perf-sort" "$P1" $k --prog sort --threads 1 --cpus "$P1" --reps 9
  crun "$k t6-sort" "$P_CPUS" $k --prog sort --threads 6 --partition tiles --cpus "$C6" --reps 9
  run "$k mesh-one" "$P1" $B --form 2 --cycles 60000 --warmup 2000 --rate 0.35 --threads 1 --cpus "$P1"
  run "$k synth-one" "$P1" $B --form 2 --chip synth --cycles 60000 --warmup 2000 --threads 1 --cpus "$P1"
done; done
sec "digests"
for key in "chip prog=sort threads=1" "chip prog=wfi" "chip prog=regs" "chip prog=sort threads=6" "chip=mesh" "chip=synth"; do
  n=$(grep -E "$key" "$RES/raw.txt" | field digest | sort -u | wc -l); [ "$n" = 1 ] && verdict "digests ($key)" PASS || verdict "digests ($key): $n distinct" FAIL
done
sec "summary: medians (us per cycle) per revision"
for t in one-sort one-wfi one-regs t6-sort; do echo "$t: $(for k in $KITS; do printf '%s %s  ' $k $(med "$k $t" us_per_cycle); done)"; done | tee "$RES/summary.txt"
for t in mesh-one synth-one; do echo "$t: $(for k in $KITS; do printf '%s %s  ' $k $(med "$k $t" us_per_chip_cycle); done)"; done | tee -a "$RES/summary.txt"
echo "perf (boot, one process, 10 machines): $(for k in $KITS; do printf '%s instr=%s cycles=%s  ' $k $(med "$k perf-sort" core_instructions) $(med "$k perf-sort" core_cycles); done)" | tee -a "$RES/summary.txt"
[ "$FAILS" = 0 ] && verdict "every run completed" PASS || verdict "every run completed ($FAILS failed)" FAIL
sec "done in $(($(date +%s) - START)) s"
} 2>&1 | tee "$RES/run.log"
grep '^VERDICT' "$RES/run.log" > "$RES/VERDICTS.txt"
rm -rf "$W"
grep -q ': FAIL$' "$RES/VERDICTS.txt" && exit 1
exit 0
